/** A death record: where and when, the WHO cause-of-death certificate (Part I lines a-d with interval and ICD code, Part II, manner, external cause, surgery, pregnancy, a baby's details), the certifier's stamp, the handover. */
export interface DeathRecordOut {
  death_id: number;
  /** e.g. DTH-2026-00001, printed on the certificate */
  death_number: string;
  patient_id: number;
  setting: "Inpatient" | "Emergency" | "Outpatient" | "BroughtDead";
  /** Inpatient: the stay the patient died in */
  admission_id: number | null;
  admission_number: string | null;
  ward_name: string | null;
  bed_label: string | null;
  /** The emergency or OPD visit, when there was one */
  ticket_id: number | null;
  ticket_number: string | null;
  /** A medico-legal death: its case in the MLC register */
  mlc_id: number | null;
  mlc_number: string | null;
  mlc_status: "Open" | "Closed" | null;
  /** Brought dead: when the body was received */
  arrived_at: string | null;
  death_at: string;
  death_at_estimated: boolean;
  pronounced_by: number;
  pronounced_by_name: string;
  pronounced_at: string;
  terminal_event: string | null;
  resuscitation_attempted: boolean | null;
  /** False: an unexpected death, reviewed as a sentinel event (MSDS 106) */
  expected_death: boolean | null;
  /** Part I (a): the disease or condition leading directly to death */
  cause_a: string | null;
  /** Approximate interval from onset to death, e.g. "2 days" */
  cause_a_interval: string | null;
  cause_a_icd: string | null;
  /** Part I (b): due to (or as a consequence of) this */
  cause_b: string | null;
  cause_b_interval: string | null;
  cause_b_icd: string | null;
  cause_c: string | null;
  cause_c_interval: string | null;
  cause_c_icd: string | null;
  cause_d: string | null;
  cause_d_interval: string | null;
  cause_d_icd: string | null;
  /** Part II: other significant conditions contributing to the death */
  other_conditions: string | null;
  other_conditions_icd: string[];
  /** The lowest line of Part I filled: the underlying cause as certified */
  underlying_cause: string | null;
  underlying_icd: string | null;
  /** The underlying cause's code with its title and WHO URI */
  underlying_term: IcdTermOut | null;
  /** Every code on the certificate with its title and WHO URI */
  icd_terms: IcdTermOut[];
  manner: "Disease" | "Accident" | "IntentionalSelfHarm" | "Assault" | "LegalIntervention" | "War" | "PendingInvestigation" | "CouldNotBeDetermined" | null;
  external_cause_date: string | null;
  /** An injury: how it happened; a poisoning: the agent */
  external_cause: string | null;
  external_cause_place: "Home" | "ResidentialInstitution" | "SchoolOrPublicBuilding" | "SportsArea" | "StreetOrHighway" | "TradeOrServiceArea" | "IndustrialOrConstruction" | "Farm" | "Other" | "Unknown" | null;
  surgery_within_4_weeks: boolean | null;
  surgery_date: string | null;
  surgery_reason: string | null;
  pregnancy_status: "NotPregnant" | "AtDeath" | "Within42Days" | "Within1Year" | "Unknown" | null;
  pregnancy_contributed: "Yes" | "No" | "Unknown" | null;
  multiple_pregnancy: boolean | null;
  /** A baby who died within 24 hours of birth: completed hours */
  hours_survived: number | null;
  birth_weight_grams: number | null;
  gestation_weeks: number | null;
  mother_age_years: number | null;
  /** Perinatal death: the mother's conditions that affected the baby */
  maternal_conditions: string | null;
  status: "Draft" | "Certified";
  certified_by: number | null;
  certified_at: string | null;
  certifier_name: string | null;
  certifier_designation: string | null;
  /** e.g. "PMDC 12345-P", frozen at certification */
  certifier_license: string | null;
  body_released_at: string | null;
  body_released_by: number | null;
  body_released_by_name: string | null;
  body_released_to: "NextOfKin" | "Police" | "Mortuary" | "Other" | null;
  receiver_name: string | null;
  receiver_relationship: string | null;
  receiver_id_number: string | null;
  receiver_phone: string | null;
  police_reference: string | null;
  release_note: string | null;
  recorded_by: number;
  created_at: string;
  row_version: number;
}

